use blake3::Hasher;
use std::fs::File;
use std::io::{BufReader, Read, Result};
use std::path::Path;

/// Computes the BLAKE3 hash of a file by streaming it in chunks.
/// Returns a `std::io::Result` to propagate I/O errors cleanly.
pub fn hash_file_streaming(path: &Path) -> Result<blake3::Hash> {
