    // Use a 64 KiB buffer for efficient I/O.
    let mut reader = BufReader::with_capacity(64 * 1024, file);
    let mut hasher = Hasher::new();

    let mut buffer = [0u8; 64 * 1024];

    loop {
        let bytes_read = reader.read(&mut buffer)?;

